const headers = $json.headers ?? {};
const tokenHeader = String(headers['x-govhub-token'] || headers['X-GOVHUB-TOKEN'] || '').trim();
const allowed = String($env.GOVHUB_TOKENS || '').split(',').map(v => v.trim()).filter(Boolean);
if (!tokenHeader || !allowed.includes(tokenHeader)) {
  return [{ json: { route: 'error', statusCode: 401, status: 'unauthorized', error_code: 'AUTH_INVALID_TOKEN', message: 'invalid token' } }];
}
let tokenScopes = [];
let rawScopes = '';
try {
  rawScopes = String($env.GOVHUB_TOKEN_SCOPES_JSON || '').trim();
  if (rawScopes) {
    const parsed = JSON.parse(rawScopes);
    if (Array.isArray(parsed[tokenHeader])) tokenScopes = parsed[tokenHeader].map((s) => String(s).trim());
  }
} catch {}
if (tokenScopes.length === 0 && rawScopes === '') {
  tokenScopes = ['s:w'];
}
if (!(tokenScopes.includes('s:r') || tokenScopes.includes('snapshots:read') || tokenScopes.includes('s:w') || tokenScopes.includes('snapshots:write'))) {
  return [{ json: { route: 'error', statusCode: 403, status: 'forbidden', error_code: 'AUTH_SCOPE_REQUIRED', message: 'token missing required read scope (s:r)' } }];
}
const query = ($json.query && typeof $json.query === 'object') ? $json.query : {};
const snapshot_type = query.snapshot_type ? String(query.snapshot_type).trim() : '';
if (!snapshot_type) {
  return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'SNAPSHOT_TYPE_REQUIRED', message: 'snapshot_type is required' } }];
}
const esc = (v) => String(v).replace(/'/g, "''");
return [{ json: { route: 'valid', snapshot_type, snapshot_type_sql: esc(snapshot_type) } }];
